import sys

def solve():
    s = sys.stdin.read().strip()
    if not s:
        print(0)
        return
    stack = [-1]
    max_len = 0
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_len = max(max_len, i - stack[-1])
    print(max_len)

if __name__ == '__main__':
    solve()

