#include <stdio.h>
#include <string.h>

int stack[35005];

int main() {
    char s[35005];
    if (scanf("%s", s) != 1) {
        printf("0\n");
        return 0;
    }
    int top = 0;
    stack[top] = -1;
    int maxLen = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == '(') {
            stack[++top] = i;
        } else {
            top--;
            if (top < 0) {
                stack[++top] = i;
            } else {
                int cur = i - stack[top];
                if (cur > maxLen) maxLen = cur;
            }
        }
    }
    printf("%d\n", maxLen);
    return 0;
}
